def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me, last_opp = my[-1], op[-1]

    opD = 0
    for x in op:
        if x == 'D':
            opD += 1

    myD = 0
    for x in my:
        if x == 'D':
            myD += 1

    oppDrun = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        oppDrun += 1
        i -= 1

    mutualDrun = 0
    i = n - 1
    while i >= 0 and my[i] == 'D' and op[i] == 'D':
        mutualDrun += 1
        i -= 1

    oppCrun = 0
    i = n - 1
    while i >= 0 and op[i] == 'C':
        oppCrun += 1
        i -= 1

    r5 = sum(1 for x in op[-5:] if x == 'D')
    r10 = sum(1 for x in op[-10:] if x == 'D')

    if opD == 0:
        return 'C'

    if n < 3:
        if opD == n or last_opp == 'D':
            return 'D'
        return 'C'

    ctx = (last_me, last_opp)
    d1 = 0
    c1 = 0
    for i in range(n - 1):
        if my[i] == ctx[0] and op[i] == ctx[1]:
            c1 += 1
            if op[i + 1] == 'D':
                d1 += 1

    d2 = 0
    c2 = 0
    for i in range(n - 1):
        if op[i] == last_opp:
            c2 += 1
            if op[i + 1] == 'D':
                d2 += 1

    rate = opD / n
    recent_rate = r5 / min(n, 5)

    base = 0.28 + 0.22 * rate + 0.32 * recent_rate
    if last_opp == 'D':
        base += 0.18
    else:
        base -= 0.08
    if myD > opD + 2:
        base -= 0.15

    if base < 0.05:
        base = 0.05
    if base > 0.95:
        base = 0.95

    if c1 >= 4:
        p = (d1 + 1.0) / (c1 + 2.0)
        p = 0.55 * p + 0.45 * base
    elif c2 >= 8:
        p = (d2 + 1.0) / (c2 + 2.0)
        p = 0.35 * p + 0.65 * base
    else:
        p = base

    if p < 0.05:
        p = 0.05
    if p > 0.95:
        p = 0.95

    if n >= 7 and last_opp == 'C' and oppCrun >= 3 and p <= 0.55:
        if r10 <= 6 or myD > opD:
            return 'C'

    if n >= 4:
        if r5 >= 4 and (last_opp == 'D' or oppCrun <= 1):
            return 'D'
        if n >= 8 and r10 >= 7 and oppCrun <= 2:
            return 'D'
        if opD * 10 >= 8 * n and r5 >= 3 and oppCrun <= 3 and p > 0.5:
            return 'D'

    if last_opp == 'D' and last_me == 'C':
        return 'D'

    if p > 0.68:
        if r5 >= 2 or opD >= 3:
            if not (last_opp == 'C' and oppCrun >= 2 and myD > opD):
                return 'D'

    if p < 0.32:
        if last_opp == 'D' and last_me == 'D' and oppDrun == 1 and opD <= max(3, n // 5):
            return 'C'
        return 'C'

    if last_opp == 'D':
        if mutualDrun >= 2:
            return 'C'
        if oppDrun >= 2:
            return 'D'
        if last_me == 'D':
            if opD <= max(3, n // 3):
                return 'C'
            return 'D'
        return 'D'

    return 'C'
